CREATE TABLE IF NOT EXISTS execution_assurance_indices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),scope_id UUID NOT NULL,factors JSONB NOT NULL,mandatory_gates JSONB NOT NULL,score NUMERIC NOT NULL CHECK(score BETWEEN 0 AND 100),overridden BOOLEAN NOT NULL,failed_gates JSONB NOT NULL,computed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settlement_assurance_indices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),scope_id UUID NOT NULL,factors JSONB NOT NULL,active_hold BOOLEAN NOT NULL,score NUMERIC NOT NULL CHECK(score BETWEEN 0 AND 100),overridden BOOLEAN NOT NULL,computed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS kpi_definitions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),kind TEXT NOT NULL CHECK(kind IN('PORTFOLIO','EXECUTION','EVIDENCE','RISK','PAYMENT','SETTLEMENT')),name TEXT NOT NULL,target_value NUMERIC NOT NULL,direction TEXT NOT NULL CHECK(direction IN('HIGHER_IS_BETTER','LOWER_IS_BETTER')),unit TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('ACTIVE','RETIRED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS kpi_values(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),kpi_definition_id UUID NOT NULL REFERENCES kpi_definitions(id),scope_id UUID NOT NULL,actual_value NUMERIC NOT NULL,on_track BOOLEAN NOT NULL,recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dashboard_snapshots(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),role TEXT NOT NULL,widgets JSONB NOT NULL,generated_for UUID NOT NULL,generated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS execution_forecasts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),scope_id UUID NOT NULL,forecast_type TEXT NOT NULL CHECK(forecast_type IN('DELAY','QUALITY','EVIDENCE','CERTIFICATION')),model_id TEXT NOT NULL,model_version TEXT NOT NULL,predicted_value NUMERIC NOT NULL,confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),rationale TEXT NOT NULL,review_status TEXT NOT NULL CHECK(review_status IN('NOT_REVIEWED','ACCEPTED','REJECTED')),generated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS execution_assurance_indices_scope_idx ON execution_assurance_indices(workspace_id,scope_id);CREATE INDEX IF NOT EXISTS settlement_assurance_indices_scope_idx ON settlement_assurance_indices(workspace_id,scope_id);CREATE INDEX IF NOT EXISTS kpi_values_definition_scope_idx ON kpi_values(workspace_id,kpi_definition_id,scope_id);CREATE INDEX IF NOT EXISTS dashboard_snapshots_role_idx ON dashboard_snapshots(workspace_id,role);CREATE INDEX IF NOT EXISTS execution_forecasts_scope_type_idx ON execution_forecasts(workspace_id,scope_id,forecast_type);
ALTER TABLE execution_assurance_indices ENABLE ROW LEVEL SECURITY;ALTER TABLE settlement_assurance_indices ENABLE ROW LEVEL SECURITY;ALTER TABLE kpi_definitions ENABLE ROW LEVEL SECURITY;ALTER TABLE kpi_values ENABLE ROW LEVEL SECURITY;ALTER TABLE dashboard_snapshots ENABLE ROW LEVEL SECURITY;ALTER TABLE execution_forecasts ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['execution_assurance_indices','settlement_assurance_indices','kpi_definitions','kpi_values','dashboard_snapshots','execution_forecasts'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['execution_assurance_indices','settlement_assurance_indices','kpi_definitions','kpi_values','dashboard_snapshots','execution_forecasts'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
